#!/usr/bin/env python3
"""Replace only GNOME-generated initials icons, not chosen user photos."""
import configparser
import pwd
import struct
import subprocess
from pathlib import Path

IMAGE = Path("/usr/share/pixmaps/faces/astra-retro-os.png")
USERS = Path("/var/lib/AccountsService/users")
ICONS = Path("/var/lib/AccountsService/icons")

def generated_icon(path: Path) -> bool:
    """GNOME Initial Setup stamps autogenerated PNGs with source metadata."""
    if not path.is_file() or path.stat().st_size > 10_000_000:
        return False
    with path.open("rb") as fp:
        if fp.read(8) != b"\x89PNG\r\n\x1a\n":
            return False
        while True:
            header = fp.read(8)
            if len(header) != 8:
                return False
            size, kind = struct.unpack(">I4s", header)
            if size > 10_000_000:
                return False
            data = fp.read(size)
            crc = fp.read(4)
            if len(data) != size or len(crc) != 4:
                return False
            if kind == b"tEXt" and data.startswith(b"source\x00"):
                return data.partition(b"\x00")[2] == b"gnome-generated"
            if kind == b"IEND":
                return False

def main():
    if not IMAGE.is_file() or not USERS.is_dir():
        return
    for user in pwd.getpwall():
        if user.pw_uid < 1000 or user.pw_uid >= 60000:
            continue
        cfg = USERS / user.pw_name
        icon = ICONS / user.pw_name
        if not cfg.is_file() or not generated_icon(icon):
            continue
        profile = configparser.ConfigParser(interpolation=None)
        profile.read(cfg)
        # Only update GNOME's own generated icon in the default icon store.
        # Never touch a user's custom profile icon or hand-selected photo.
        if not profile.has_section("User"):
            continue
        current = profile.get("User", "Icon", fallback="")
        if current != str(icon):
            continue
        path = f"/org/freedesktop/Accounts/User{user.pw_uid}"
        subprocess.run(["busctl", "--system", "call", "org.freedesktop.Accounts",
            path, "org.freedesktop.Accounts.User", "SetIconFile", "s", str(IMAGE)],
            check=True)

if __name__ == "__main__":
    main()
